package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;
public final class PcHudReferenceExport {
 static void bytes(DataOutputStream out,ByteBuffer b)throws Exception{byte[] data=new byte[b.remaining()];b.get(data);out.write(data);}
 static void write(Path output,String name,NativeSceneSnapshot s)throws Exception{NativeHudFrame h=new NativeHudFrame(s);ByteBuffer c=h.colors();int cells=0;for(int i=3;i<c.remaining();i+=4)if(c.get(i)!=0)cells++;try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(output.resolve(name+".hud")))){out.writeLong(s.epoch);out.writeLong(s.refresh);out.writeLong(cells);bytes(out,h.colors());bytes(out,h.metadata());for(int y=0;y<160;y++)for(int v:h.parameters(y))out.writeInt(Integer.reverseBytes(v));}ByteBuffer layers=s.packedLayers();byte[] packed=new byte[layers.remaining()];layers.get(packed);Files.write(output.resolve(name+".nlp"),packed);}
 public static void main(String[]args)throws Exception{Path input=Paths.get(args[0]),legacy=Paths.get(args[1]),output=Paths.get(args[2]);Files.createDirectories(output);int count=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(input,"source-race-background-*.nrb")){for(Path file:files){NativeSceneSnapshot s=new NativeBackgroundScene(Files.readAllBytes(file)).sky.scene;write(output,Long.toString(s.refresh),s);count++;}}for(String name:new String[]{"whole","split"}){write(output,"legacy-"+name,new NativeSceneSnapshot(Files.readAllBytes(legacy.resolve(name+".nab"))));count++;}write(output,"synthetic-effects",new NativeSceneSnapshot(Files.readAllBytes(Paths.get(args[3]))));count++;if(count!=12)throw new AssertionError();System.out.println("PASS_PC_HUD_EXPORT frames="+count+" rows="+count*160);}
}
